#!/usr/bin/env bash
# Build -> check -> snapshot -> render -> validate one project.
# Usage: scripts/produce.sh projects/<slug> [--final] [--no-build]
#   (default)   draft preview  -> projects/<slug>/previews/<slug>.mp4   (quality: draft)
#   --final     final render   -> projects/<slug>/exports/<slug>.mp4    (quality: delivery)
#   --no-build  keep hyperframes/ as is (for projects whose compositions are generated by another tool,
#               e.g. md_to_video.py); still bundles GSAP, checks, renders and validates
# Every step must pass; nothing is called "done" unless scripts/validate_video.py passes on the MP4.
# A failed render never replaces an existing good file (renders to a temp name first).
set -euo pipefail
proj="${1:?usage: produce.sh projects/<slug> [--final] [--no-build]}"; shift || true
final=0; build=1
for a in "$@"; do case "$a" in --final) final=1;; --no-build) build=0;; *) echo "unknown option $a" >&2; exit 2;; esac; done

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
proj="$(cd "$proj" && pwd)"
slug="$(basename "$proj")"
hf="$proj/hyperframes"
HF="npx --yes hyperframes@0.8.199"
step() { printf '\n== %s\n' "$*"; }

[ -f "$hf/hyperframes.json" ] || { echo "$hf is not a HyperFrames project" >&2; exit 1; }

if [ "$build" = 1 ]; then
  step "1/6 generate compositions from edit.json"
  python3 "$root/scripts/build_edit.py" "$proj"
fi

step "2/6 bundle GSAP locally (no CDN)"
bash "$root/scripts/vendor_gsap.sh" "$hf"
if grep -rqE "src=\"https?://|href=\"https?://|url\(https?://" "$hf" --include=*.html --exclude-dir=node_modules; then
  echo "External URL left in a composition (blocked in cloud sessions, breaks offline renders):" >&2
  grep -rnE "src=\"https?://|href=\"https?://|url\(https?://" "$hf" --include=*.html --exclude-dir=node_modules >&2
  exit 1
fi

step "3/6 make sure the render browser is installed"
$HF browser ensure >/dev/null 2>&1 || true

step "4/6 hyperframes check (lint + runtime + layout)"
mkdir -p "$proj/work"
if ! (cd "$hf" && $HF check --json > "$proj/work/check.json"); then
  python3 - "$proj/work/check.json" <<'EOF'
import json, sys
try:
    d = json.load(open(sys.argv[1]))
except Exception as exc:
    print("check output unreadable:", exc); sys.exit(0)
print(json.dumps(d, indent=2)[:4000])
EOF
  echo "hyperframes check failed: fix the findings above and rerun" >&2
  exit 1
fi
echo "check passed ($proj/work/check.json)"

step "5/6 snapshot key frames for review"
(cd "$hf" && $HF snapshot --frames 6 -o "$proj/previews/snapshots" >/dev/null 2>&1) && echo "frames: $proj/previews/snapshots" || echo "snapshot skipped (non-fatal)"

if [ "$final" = 1 ]; then dest="$proj/exports/$slug.mp4"; q=delivery; else dest="$proj/previews/$slug.mp4"; q=draft; fi
mkdir -p "$(dirname "$dest")"
tmp="${dest%.mp4}.rendering.mp4"; rm -f "$tmp"
step "6/6 render ($q) and validate"
(cd "$hf" && $HF render -q "$q" -o "$tmp")
python3 "$root/scripts/validate_video.py" "$tmp" --project "$hf" --size "$(python3 -c "import json;m=json.load(open('$proj/project.json'));print(f\"{m['width']}x{m['height']}\")" 2>/dev/null || echo 1920x1080)"
mv -f "$tmp" "$dest"
printf '\nDONE  %s\n' "$dest"
